create or replace function public.maths_start_daily() returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); day_ int:=maths._study_day(); s maths.sessions%rowtype; size_ int:=greatest(1,coalesce(nullif(maths._setting('daily_chapter_size','25'),'')::int,25)); ids text[]; comp jsonb; begin perform pg_advisory_xact_lock(hashtext(uid::text||':maths-daily:'||day_::text)); select * into s from maths.sessions where user_id=uid and lower(coalesce(mode,''))='daily' and coalesce(nullif(params->>'planDay','')::int,0)=day_ order by completed desc,updated_at desc nulls last limit 1; if found then if not s.completed then return maths._get_session(uid,s.session_id); else return jsonb_build_object('ok',false,'dailyComplete',true,'message','Day '||day_||' is complete. Use Practice More for another mixed set.','sessionId',s.session_id); end if; end if; ids:=maths._select_daily_ids(uid,day_,size_,array[]::text[]); with rr as(select r.*,count(*) over(partition by r.chapter) cnt from maths._user_runtime(uid) r where r.question_id=any(ids)), ch as(select jsonb_object_agg(chapter,cnt) chapters from(select distinct chapter,cnt from rr)x) select jsonb_build_object('new',count(*) filter(where rr.state_attempts=0),'difficultDue',count(*)filter(where rr.difficult),'hard',count(*)filter(where rr.hard),'weak',count(*)filter(where rr.weak),'dueRevision',count(*)filter(where rr.profile_total>0 and rr.age_days>=rr.review_interval),'chapters',coalesce((select chapters from ch),'{}'::jsonb)) into comp from rr; return maths._start_session(uid,ids,'daily','Day '||day_||' · Mixed Revision',jsonb_build_object('planDay',day_,'planChapter','Mixed Revision','dailyComposition',comp,'dailyVersion','v20'),false); end $$;
create or replace function public.maths_start_practice_more(p_count integer default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); day_ int:=maths._study_day(); size_ int:=greatest(1,least(coalesce(p_count,nullif(maths._setting('practice_more_size','20'),'')::int,20),100)); recent text[]; ids text[]; extra text[]; begin select coalesce(array_agg(distinct sq.question_id),array[]::text[]) into recent from maths.session_questions sq join (select session_id from maths.sessions where user_id=uid and lower(coalesce(mode,'')) in('daily','practice_more') order by updated_at desc nulls last limit 2)s using(session_id); ids:=maths._select_daily_ids(uid,day_,size_,recent); if coalesce(array_length(ids,1),0)<size_ then extra:=maths._select_daily_ids(uid,day_,size_-coalesce(array_length(ids,1),0),ids); ids:=ids||extra; end if; return maths._start_session(uid,ids,'practice_more','Practice More · Mixed Revision',jsonb_build_object('planDay',day_,'practiceMore',true),false); end $$;
create or replace function public.maths_start_focused_practice(p_scope text default 'all',p_kind text default 'random',p_chapter text default null,p_topic text default null,p_group text default null,p_count integer default 20) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); base text[]; ids text[]; title text; begin base:=maths._question_ids(uid,p_scope,p_chapter,p_topic,p_group); ids:=maths._select_by_kind(uid,base,p_kind,p_count); title:=coalesce(nullif(p_topic,''),nullif(p_chapter,''),nullif(initcap(p_group),''),case when lower(p_scope)='new_practice' then 'New Practice' when lower(p_scope)='starred' then 'Starred Revision' when lower(p_scope)='generated' then 'Generated Practice' else 'Maths Practice' end)||' · '||initcap(replace(p_kind,'_',' ')); return maths._start_session(uid,ids,'maths_'||lower(p_kind),title,jsonb_build_object('scope',p_scope,'kind',p_kind,'chapter',p_chapter,'majorTopic',p_topic,'group',p_group),false); end $$;
create or replace function public.maths_start_mock_practice(p_kind text default 'random',p_chapter text default null,p_count integer default 20) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); base text[]; ids text[]; begin select coalesce(array_agg(question_id),array[]::text[]) into base from maths._user_runtime(uid) where runtime_active and in_mock and (p_chapter is null or maths._norm(chapter)=maths._norm(p_chapter)); ids:=maths._select_by_kind(uid,base,p_kind,p_count); return maths._start_session(uid,ids,'mock_questions','Mocks · '||coalesce(p_chapter,'All')||' · '||initcap(p_kind),jsonb_build_object('scope','mock_questions','setId','MOCK_QUESTIONS','kind',p_kind,'chapter',p_chapter),false); end $$;
create or replace function public.maths_start_formula_revision(p_kind text default 'all',p_chapter text default null,p_count integer default 20) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); base text[]; ids text[]; begin select coalesce(array_agg(question_id),array[]::text[]) into base from maths._user_runtime(uid) where runtime_active and in_formula_revision and (p_chapter is null or maths._norm(chapter)=maths._norm(p_chapter)); ids:=maths._select_by_kind(uid,base,p_kind,p_count); return maths._start_session(uid,ids,'formula_revision','Formula Revision · '||coalesce(p_chapter,'All')||' · '||initcap(p_kind),jsonb_build_object('scope','formula_revision','setId','MOCK_FORMULA_REVISION','kind',p_kind,'chapter',p_chapter),false); end $$;
create or replace function public.maths_start_calculation(p_mode text default 'mixed',p_type text default null,p_skill text default null,p_count integer default 20) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); base text[]; ids text[]; mode_ text:=lower(coalesce(p_mode,'mixed')); force_reveal boolean:=mode_='recall'; out_ jsonb; sid_ text; begin with c as(select r.question_id,r.profile_last_result,r.difficult,r.last_response_sec,r.state_attempts,maths._calc_type(q) typ,maths._norm(coalesce(q.topic,q.subtopic,'Mixed')) skill from maths._user_runtime(uid) r join maths.runtime_questions q using(question_id) where r.runtime_active and (r.bank_calculation or r.in_calc_set) and (maths._calc_type(q)<>'MEMORY' or maths._calc_recall_eligible(q))) select coalesce(array_agg(question_id),array[]::text[]) into base from c where (p_type is null or typ=upper(p_type)) and (p_skill is null or skill=maths._norm(p_skill)) and (mode_<>'recall' or typ='MEMORY'); if mode_ in('weak','slow') then select coalesce(array_agg(x.question_id),array[]::text[]) into ids from(select r.question_id from maths._user_runtime(uid) r where r.question_id=any(base) order by (r.profile_last_result='wrong') desc,r.difficult desc,(r.last_response_sec>=8) desc,(r.state_attempts=0) desc,r.last_response_sec desc limit greatest(1,least(coalesce(p_count,20),100)))x; elsif mode_='all' then ids:=base; else select coalesce(array_agg(x),array[]::text[]) into ids from(select unnest(base)x order by random() limit greatest(1,least(coalesce(p_count,20),100)))z; end if; if mode_='mixed' then out_:=maths._start_session(uid,ids,'calculation_speed','Calculation Training · Mixed Practice',jsonb_build_object('mode',mode_,'type',p_type,'skill',p_skill),false); sid_:=out_->>'sessionId'; if sid_ is not null then update maths.sessions s set rendered_questions=(select jsonb_agg(case when maths._calc_type(q)='MEMORY' then (e-'options'-'correctOption'-'answerMode'-'variantType')||jsonb_build_object('options','[]'::jsonb,'correctOption','','answerMode','REVEAL','variantType','CALC_RECALL') else e end order by ord) from jsonb_array_elements(s.rendered_questions) with ordinality z(e,ord) join maths.runtime_questions q on q.question_id=e->>'questionId') where s.session_id=sid_ and s.user_id=uid; return maths._get_session(uid,sid_); end if; return out_; end if; return maths._start_session(uid,ids,'calculation_speed','Calculation Training · '||case when mode_='recall' then 'Recall' when mode_ in('weak','slow') then 'Weak & Slow' when mode_='all' then 'All' else 'Mixed Practice' end,jsonb_build_object('mode',mode_,'type',p_type,'skill',p_skill),force_reveal); end $$;
create or replace function public.maths_start_concepts(p_kind text default 'random',p_chapter text default null,p_topic text default null,p_count integer default 20) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); base text[]; ids text[]; begin select coalesce(array_agg(r.question_id),array[]::text[]) into base from maths._user_runtime(uid) r join maths.concept_membership c on c.user_id=uid and c.question_id=r.question_id and c.active where r.runtime_active and (p_chapter is null or maths._norm(r.chapter)=maths._norm(p_chapter)) and (p_topic is null or maths._norm(r.major_topic)=maths._norm(p_topic)); ids:=maths._select_by_kind(uid,base,p_kind,p_count); return maths._start_session(uid,ids,'concept_saved','Concepts · '||coalesce(p_topic,p_chapter,'All')||' · '||initcap(p_kind),jsonb_build_object('scope','concept_saved','kind',p_kind,'chapter',p_chapter,'majorTopic',p_topic),false); end $$;
create or replace function public.maths_start_demand_set(p_set_id text,p_kind text default 'random',p_count integer default 20) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); base text[]; ids text[]; name_ text; begin select set_name into name_ from maths.practice_sets where user_id=uid and set_id=p_set_id and lower(coalesce(status,'active'))<>'inactive'; if not found then raise exception 'Demand set not found'; end if; select coalesce(array_agg(i.question_id order by i.sequence),array[]::text[]) into base from maths.practice_set_items i join maths.runtime_questions q on q.question_id=i.question_id and q.runtime_active where i.set_id=p_set_id; ids:=maths._select_by_kind(uid,base,p_kind,p_count); return maths._start_session(uid,ids,'demand_set',name_||' · '||initcap(p_kind),jsonb_build_object('scope','demand_set','setId',p_set_id,'kind',p_kind),false); end $$;
create or replace function public.maths_get_session(p_session_id text) returns jsonb language sql stable security definer set search_path=pg_catalog,public,maths as $$ select maths._get_session(maths._require_uid(),p_session_id) $$;
create or replace function public.maths_save_session_position(p_session_id text,p_index integer) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); n int; begin select count(*) into n from maths.session_questions sq join maths.sessions s on s.session_id=sq.session_id where s.session_id=p_session_id and s.user_id=uid; if n=0 then raise exception 'Session not found'; end if; update maths.sessions set current_index=greatest(0,least(p_index,n-1)),updated_at=now() where session_id=p_session_id and user_id=uid and not completed; return maths._get_session(uid,p_session_id); end $$;
create or replace function public.maths_submit_answer(p_session_id text,p_question_id text,p_selected_option text default null,p_response_sec numeric default 0,p_client_attempt_key text default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); s maths.sessions%rowtype; q maths.runtime_questions%rowtype; rendered jsonb; mode_ text; expected text; selected text:=upper(coalesce(p_selected_option,'')); result_ text; idx int; key_ text:=coalesce(nullif(btrim(p_client_attempt_key),''),gen_random_uuid()::text); existing maths.attempts%rowtype; st maths.question_state%rowtype; next_ int; begin perform pg_advisory_xact_lock(hashtext(uid::text||':'||p_session_id)); select * into s from maths.sessions where session_id=p_session_id and user_id=uid; if not found then raise exception 'Session not found'; end if; select * into existing from maths.attempts where client_attempt_key=key_ limit 1; if found then if existing.user_id<>uid or existing.session_id<>p_session_id or existing.question_id<>p_question_id then raise exception 'Attempt key conflict'; end if; return jsonb_build_object('ok',true,'deduped',true,'result',existing.result,'selectedOption',coalesce(existing.selected_option,''),'attemptId',existing.attempt_id); end if; if s.completed then raise exception 'Completed sessions cannot accept new attempts'; end if; select * into q from maths.runtime_questions where question_id=p_question_id and runtime_active; if not found then raise exception 'Question is missing or inactive'; end if; select e,ord::int-1 into rendered,idx from jsonb_array_elements(s.rendered_questions) with ordinality z(e,ord) where e->>'questionId'=p_question_id limit 1; if rendered is null then raise exception 'Question does not belong to this session'; end if; mode_:=upper(coalesce(rendered->>'answerMode','REVEAL')); expected:=upper(coalesce(rendered->>'correctOption','')); if mode_='MCQ' then if selected not in('A','B','C','D') then raise exception 'Selected option is required'; end if; if not exists(select 1 from jsonb_array_elements(rendered->'options') e where upper(e->>'key')=selected) then raise exception 'Selected option is invalid'; end if; result_:=case when selected=expected then 'correct' else 'wrong' end; else result_:='seen'; selected:=''; end if; insert into maths.question_state(user_id,question_id,attempts,mastered,marked,last_attempt,last_result,last_response_sec,chapter,topic,subtopic,last_variant,last_correct_option,difficult) values(uid,p_question_id,1,false,false,now(),result_,greatest(0,least(coalesce(p_response_sec,0),86400)),q.chapter,q.topic,q.subtopic,coalesce(rendered->>'variantType',''),expected,false) on conflict(user_id,question_id) do update set attempts=maths.question_state.attempts+1,last_attempt=excluded.last_attempt,last_result=excluded.last_result,last_response_sec=excluded.last_response_sec,chapter=coalesce(maths.question_state.chapter,excluded.chapter),topic=coalesce(maths.question_state.topic,excluded.topic),subtopic=coalesce(maths.question_state.subtopic,excluded.subtopic),last_variant=excluded.last_variant,last_correct_option=excluded.last_correct_option returning * into st; insert into maths.attempts(attempt_id,user_id,attempted_at,question_id,result,response_sec,mode,session_id,mastered_after,marked_after,variant_type,selected_option,question_index,client_attempt_key) values(gen_random_uuid()::text,uid,now(),p_question_id,result_,greatest(0,least(coalesce(p_response_sec,0),86400)),s.mode,p_session_id,st.mastered,st.marked,coalesce(rendered->>'variantType',''),nullif(selected,''),idx,key_); next_:=least((select count(*) from maths.session_questions where session_id=p_session_id)-1,idx+1); update maths.sessions set current_index=greatest(current_index,next_),updated_at=now() where session_id=p_session_id and user_id=uid; return jsonb_build_object('ok',true,'deduped',false,'result',result_,'correct',result_='correct','correctOption',expected,'selectedOption',selected,'attemptId',key_,'starred',st.marked,'difficult',st.difficult,'mastered',st.mastered); end $$;
create or replace function public.maths_finish_session(p_session_id text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare uid uuid:=maths._require_uid(); total_ int; done_ int; begin select count(*) into total_ from maths.session_questions sq join maths.sessions s on s.session_id=sq.session_id where s.session_id=p_session_id and s.user_id=uid; if total_=0 then raise exception 'Session not found'; end if; select count(distinct question_id) into done_ from maths.attempts where user_id=uid and session_id=p_session_id; if done_<total_ then raise exception 'Session is incomplete (% of % answered)',done_,total_; end if; update maths.sessions set completed=true,current_index=greatest(0,total_-1),updated_at=now() where session_id=p_session_id and user_id=uid; return jsonb_build_object('ok',true,'completed',true,'done',done_,'target',total_); end $$;
create or replace function maths._ensure_state(p_uid uuid,p_question_id text) returns void language plpgsql security definer set search_path=pg_catalog,public,maths as $$ declare q maths.runtime_questions%rowtype; begin select * into q from maths.runtime_questions where question_id=p_question_id and runtime_active; if not found then raise exception 'Question is missing or inactive'; end if; insert into maths.question_state(user_id,question_id,attempts,mastered,marked,chapter,topic,subtopic,difficult) values(p_uid,p_question_id,0,false,false,q.chapter,q.topic,q.subtopic,false) on conflict(user_id,question_id) do nothing; end $$;
create or replace function public.maths_set_starred(p_question_id text,p_value boolean) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$declare uid uuid:=maths._require_uid();begin perform maths._ensure_state(uid,p_question_id);update maths.question_state set marked=p_value where user_id=uid and question_id=p_question_id;return jsonb_build_object('ok',true,'questionId',p_question_id,'starred',p_value);end$$;
create or replace function public.maths_set_difficult(p_question_id text,p_value boolean) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$declare uid uuid:=maths._require_uid();begin perform maths._ensure_state(uid,p_question_id);update maths.question_state set difficult=p_value where user_id=uid and question_id=p_question_id;return jsonb_build_object('ok',true,'questionId',p_question_id,'difficult',p_value);end$$;
create or replace function public.maths_set_mastered(p_question_id text,p_value boolean) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$declare uid uuid:=maths._require_uid();begin perform maths._ensure_state(uid,p_question_id);update maths.question_state set mastered=p_value where user_id=uid and question_id=p_question_id;return jsonb_build_object('ok',true,'questionId',p_question_id,'mastered',p_value);end$$;
create or replace function public.maths_set_concept(p_question_id text,p_value boolean) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$declare uid uuid:=maths._require_uid();q maths.runtime_questions%rowtype;begin select * into q from maths.runtime_questions where question_id=p_question_id and runtime_active;if not found then raise exception 'Question is missing or inactive';end if;insert into maths.concept_membership(question_id,added_at,study_day,chapter,topic,session_id,active,user_id) values(p_question_id,now(),maths._study_day(),q.chapter,q.topic,null,p_value,uid) on conflict(user_id,question_id) do update set active=excluded.active,chapter=excluded.chapter,topic=excluded.topic;return jsonb_build_object('ok',true,'questionId',p_question_id,'inConcept',p_value);end$$;
create or replace function public.maths_save_note(p_question_id text,p_note text,p_pinned boolean default false) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,maths as $$declare uid uuid:=maths._require_uid();begin if not exists(select 1 from maths.runtime_questions where question_id=p_question_id and runtime_active)then raise exception 'Question is missing or inactive';end if;insert into maths.user_notes(user_id,question_id,note,updated_at,pinned,source_row,migration_run_id) values(uid,p_question_id,coalesce(p_note,''),now(),coalesce(p_pinned,false),'{}'::jsonb,null) on conflict(user_id,question_id) do update set note=excluded.note,updated_at=excluded.updated_at,pinned=excluded.pinned;return jsonb_build_object('ok',true,'questionId',p_question_id,'saved',true);end$$;
create or replace function public.maths_get_local_safe_health() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,maths as $$declare uid uuid:=maths._require_uid();begin return jsonb_build_object('ok',true,'readOnly',true,'studyDay',maths._study_day(),'userId',uid,'dailyTarget',coalesce(nullif(maths._setting('daily_chapter_size','25'),'')::int,25));end$$;


